        prog =
          typeof createEmptyProgress === 'function'
            ? createEmptyProgress(firstId)
            : {
                slideId: firstId,
                completedTaskIds: [],
                onEnterDoneSlideIds: [],
                completed: false,
                timestamp: Date.now()
              };
